use aa_rules::{actors::ActorCatalog,sources::{SourceLimits,V14Sources},native::TypedValue};
use aa_numeric::Precision;
fn main(){let root=std::path::Path::new(r"E:\Games\Axis and Alies");let mut files=V14Sources::open(root.join("Data.rwd"),root.join("reconstruction/native-game/runtime-expanded-v14"),SourceLimits{max_member_bytes:u64::MAX}).unwrap();let source=ActorCatalog::load_v14(&mut files).unwrap();let data:serde_json::Value=serde_json::from_slice(&std::fs::read("research/skirmish-20261017-recruit-eligibility/actual-source-inputs.json").unwrap()).unwrap();for d in data["definitions"].as_array().unwrap(){let id=d["ids"].as_str().unwrap();let node=source.resolved_actor(id).unwrap();print!("{id} hide={:?}",node.field("hide_if_missing_properties",Precision::Double53).unwrap());if let Some(element)=node.child("ElementComponent").unwrap(){for field in["required_structures","required_properties"]{let value=element.field(field,Precision::Double53).unwrap();print!(" {field}={:?}",value);}}println!();}}
